int a = 5, b = 3;
int result = a & b;
System.out.println(result + " (" + Integer.toBinaryString(result) + ")");

int a = 5, b = 3;
int result = a | b;
System.out.println(result + " (" + Integer.toBinaryString(result) + ")");

int a = 5, b = 3;
int result = a ^ b;
System.out.println(result + " (" + Integer.toBinaryString(result) + ")");

int a = 5;
int result = ~a;
System.out.println(result + " (" + Integer.toBinaryString(result) + ")");

int a = 5;
System.out.println(a << 1); // 10 (5*2)
System.out.println(a << 2); // 20 (5*4)
// Przesunięcie w lewo o n bitów jest równoważne mnozeniu przez 2^n.

int a = 20;
System.out.println(a >> 1); // 10 (20/2)
System.out.println(a >> 2); // 5 (20/4)
// Przesunięcie w prawo o n bitów jest równoważne dzieleniu calkowitoliczbowemu przez 2^n.

int neg = -8;
System.out.println(neg >> 1);  // -4 (zachowuje znak)
System.out.println(neg >>> 1); // ogromna liczba dodatnia (wypełnia zerami)
// >> (signed) wypełnia nowe bity ZNAKIEM (jedynkami dla ujemnych) - zachowuje ujemnosc.
// >>> (unsigned) ZAWSZE wypełnia zerami, niezależnie od znaku - dla liczb ujemnych
// daje całkowicie inny, DUZY DODATNI wynik.

int a = 12, b = 10;
System.out.println("a & b = " + (a & b));
System.out.println("a | b = " + (a | b));
System.out.println("a ^ b = " + (a ^ b));
System.out.println("~a = " + (~a));
System.out.println("a << 1 = " + (a << 1));
System.out.println("a >> 1 = " + (a >> 1));

int n = 7;
int mul = n * 2;
int shift = n << 1;
System.out.println("n*2 = " + mul);
System.out.println("n<<1 = " + shift);
System.out.println("Równe: " + (mul == shift));

int n = 64;
System.out.println("n/2 = " + (n / 2));
System.out.println("n>>1 = " + (n >> 1));

int[] numbers = {4, 7, 10, 13, 16};
for (int n : numbers) {
    boolean isEven = (n & 1) == 0;
    System.out.println(n + " parzysta: " + isEven);
}

int permissions = 0;
permissions |= (1 << 0); // READ
permissions |= (1 << 1); // WRITE
System.out.println(Integer.toBinaryString(permissions));

int permissions = 0b0110;
System.out.println("READ: " + ((permissions & 1) != 0));
System.out.println("WRITE: " + ((permissions & (1 << 1)) != 0));
System.out.println("EXECUTE: " + ((permissions & (1 << 2)) != 0));

int permissions = 0b0111;
System.out.println("Przed: " + Integer.toBinaryString(permissions));
permissions &= ~(1 << 1);
System.out.println("Po: " + Integer.toBinaryString(permissions));

int state = 0b1010;
System.out.println("Poczatek: " + Integer.toBinaryString(state));
state ^= (1 << 3);
System.out.println("Po 1. przelaczeniu: " + Integer.toBinaryString(state));
state ^= (1 << 3);
System.out.println("Po 2. przelaczeniu: " + Integer.toBinaryString(state));

int a = 10, b = 20;
System.out.println("Przed: a=" + a + ", b=" + b);
a = a ^ b;
b = a ^ b;
a = a ^ b;
System.out.println("Po: a=" + a + ", b=" + b);

final int FLAG_ACTIVE = 1 << 0;
final int FLAG_ADMIN = 1 << 1;
final int FLAG_OWNER = 1 << 2;
final int FLAG_BANNED = 1 << 3;

int permissions = FLAG_ACTIVE | FLAG_ADMIN;
System.out.println("Poczatkowe: " + Integer.toBinaryString(permissions));

boolean isAdmin = (permissions & FLAG_ADMIN) != 0;
System.out.println("Admin: " + isAdmin);

permissions &= ~FLAG_ACTIVE;
System.out.println("Po usunieciu ACTIVE: " + Integer.toBinaryString(permissions));

int byteVal = 0xAB;
int low = byteVal & 0x0F;
int high = (byteVal >> 4) & 0x0F;
System.out.println("Low nibble: " + low);
System.out.println("High nibble: " + high);

for (int i = 0; i <= 15; i++) {
    int power = 1 << i;
    System.out.println("2^" + i + " = " + power);
}

int n = -42;
int mask = n >> 31;
int abs = (n ^ mask) - mask;
System.out.println("Bitowo: " + abs);
System.out.println("Math.abs: " + Math.abs(-42));

int n = 42;
int original = n;
int count = 0;
while (n != 0) {
    count += n & 1;
    n >>= 1;
}
System.out.println("Ręcznie: " + count);
System.out.println("Integer.bitCount: " + Integer.bitCount(original));

int n = 0b10110100;
int reversed = 0;
int temp = n;
for (int i = 0; i < 8; i++) {
    reversed = (reversed << 1) | (temp & 1);
    temp >>= 1;
}
System.out.println("Oryginał: " + Integer.toBinaryString(n));
System.out.println("Odwrocony: " + Integer.toBinaryString(reversed));

int[] values = {1, 2, 3, 4, 5, 8, 16, 100, 128};
for (int n : values) {
    boolean isPowerOfTwo = n > 0 && (n & (n - 1)) == 0;
    System.out.println(n + ": " + isPowerOfTwo);
}

int n = 42;
for (int pos = 0; pos <= 5; pos++) {
    int bit = (n >> pos) & 1;
    System.out.println("Bit na pozycji " + pos + ": " + bit);
}

String message = "Hello";
int key = 42;
char[] chars = message.toCharArray();
char[] encrypted = new char[chars.length];
for (int i = 0; i < chars.length; i++) {
    encrypted[i] = (char) (chars[i] ^ key);
}
String encryptedStr = new String(encrypted);
System.out.println("Zaszyfrowane (kody): " + java.util.Arrays.toString(encrypted));

char[] decrypted = new char[encrypted.length];
for (int i = 0; i < encrypted.length; i++) {
    decrypted[i] = (char) (encrypted[i] ^ key);
}
System.out.println("Odszyfrowane: " + new String(decrypted));

int a = 10, b = 20, c = 30, d = 40;
int packed = (a << 24) | (b << 16) | (c << 8) | d;
System.out.println("Packed: " + packed);

int a2 = (packed >> 24) & 0xFF;
int b2 = (packed >> 16) & 0xFF;
int c2 = (packed >> 8) & 0xFF;
int d2 = packed & 0xFF;
System.out.println("Odzyskane: " + a2 + ", " + b2 + ", " + c2 + ", " + d2);

int data = 0b11001010;
int cleared = data & 0b11110000;
int set = data | 0b00001111;
System.out.println("Wyzerowane dolne 4: " + Integer.toBinaryString(cleared));
System.out.println("Ustawione dolne 4: " + Integer.toBinaryString(set));

int n = 42;
int temp = n;
int position = -1;
while (temp != 0) {
    temp >>= 1;
    position++;
}
System.out.println("Ręcznie: pozycja " + position);
System.out.println("Wbudowana: " + (31 - Integer.numberOfLeadingZeros(n)));

int a = 5, b = 3;
while (b != 0) {
    int carry = a & b;
    a = a ^ b;
    b = carry << 1;
}
System.out.println("5 + 3 = " + a);

int x = 10, y = 15;
while (y != 0) {
    int carry = x & y;
    x = x ^ y;
    y = carry << 1;
}
System.out.println("10 + 15 = " + x);

final int DARK_MODE = 1 << 0;
final int NOTIFICATIONS = 1 << 1;
final int AUTO_SAVE = 1 << 2;
final int BETA_FEATURES = 1 << 3;

int settings = DARK_MODE | AUTO_SAVE;
System.out.println("Poczatkowe: " + Integer.toBinaryString(settings));

settings |= NOTIFICATIONS;
System.out.println("Po dodaniu NOTIFICATIONS: " + Integer.toBinaryString(settings));

settings &= ~AUTO_SAVE;
System.out.println("Po usunieciu AUTO_SAVE: " + Integer.toBinaryString(settings));

settings ^= DARK_MODE;
System.out.println("Po przelaczeniu DARK_MODE: " + Integer.toBinaryString(settings));

